INSERT INTO interpretation_templates (language, factor_type, factor_value_1, factor_value_2, title, content, keywords) VALUES ('en', 'planet_in_sign', 'Sun', 'Aries', 'Sun in Aries', 'With Sun in Aries, the themes of core identity, vitality, and ego take on a direct, pioneering, and energetic flavor. This placement infuses your chart with unique characteristics, blending the planet''s core energy with the sign''s modality and element.', ARRAY['core identity, vitality', 'ego', 'direct, pioneering', 'energetic']);
INSERT INTO interpretation_templates (language, factor_type, factor_value_1, factor_value_2, title, content, keywords) VALUES ('vi', 'planet_in_sign', 'Sun', 'Aries', 'Sao Sun ở Aries', 'Với Sao Sun ở Aries, các chủ đề về bản sắc cốt lõi, sức sống và cái tôi mang một sắc thái trực tiếp, tiên phong và tràn đầy năng lượng. Vị trí này truyền vào bản đồ sao của bạn những đặc điểm độc đáo, kết hợp năng lượng cốt lõi của hành tinh với đặc tính và nguyên tố của cung hoàng đạo.', ARRAY['bản sắc cốt lõi, sức sống', 'cái tôi', 'trực tiếp, tiên phong', 'tràn đầy năng lượng']);
