INSERT INTO interpretation_templates (language, factor_type, factor_value_1, factor_value_2, title, content, keywords) VALUES ('en', 'planet_in_sign', 'Moon', 'Libra', 'Moon in Libra', 'With Moon in Libra, the themes of emotions, instincts, and subconscious take on a harmonious, diplomatic, and partnership-focused flavor. This placement infuses your chart with unique characteristics, blending the planet''s core energy with the sign''s modality and element.', ARRAY['emotions, instincts', 'subconscious', 'harmonious, diplomatic', 'partnership-focused']);
INSERT INTO interpretation_templates (language, factor_type, factor_value_1, factor_value_2, title, content, keywords) VALUES ('vi', 'planet_in_sign', 'Moon', 'Libra', 'Sao Moon ở Libra', 'Với Sao Moon ở Libra, các chủ đề về cảm xúc, bản năng và tiềm thức mang một sắc thái hài hòa, ngoại giao và hướng tới quan hệ đối tác. Vị trí này truyền vào bản đồ sao của bạn những đặc điểm độc đáo, kết hợp năng lượng cốt lõi của hành tinh với đặc tính và nguyên tố của cung hoàng đạo.', ARRAY['cảm xúc, bản năng', 'tiềm thức', 'hài hòa, ngoại giao', 'hướng tới quan hệ đối tác']);
INSERT INTO interpretation_templates (language, factor_type, factor_value_1, factor_value_2, title, content, keywords) VALUES ('en', 'planet_in_sign', 'Moon', 'Scorpio', 'Moon in Scorpio', 'With Moon in Scorpio, the themes of emotions, instincts, and subconscious take on a intense, passionate, and investigative flavor. This placement infuses your chart with unique characteristics, blending the planet''s core energy with the sign''s modality and element.', ARRAY['emotions, instincts', 'subconscious', 'intense, passionate', 'investigative']);
