INSERT INTO interpretation_templates (language, factor_type, factor_value_1, factor_value_2, title, content, keywords) VALUES ('en', 'planet_in_sign', 'Moon', 'Aquarius', 'Moon in Aquarius', 'With Moon in Aquarius, the themes of emotions, instincts, and subconscious take on a progressive, unconventional, and visionary flavor. This placement infuses your chart with unique characteristics, blending the planet''s core energy with the sign''s modality and element.', ARRAY['emotions, instincts', 'subconscious', 'progressive, unconventional', 'visionary']);
