INSERT INTO interpretation_templates (language, factor_type, factor_value_1, factor_value_2, title, content, keywords) VALUES ('en', 'planet_in_sign', 'Moon', 'Pisces', 'Moon in Pisces', 'With Moon in Pisces, the themes of emotions, instincts, and subconscious take on a empathetic, mystical, and imaginative flavor. This placement infuses your chart with unique characteristics, blending the planet''s core energy with the sign''s modality and element.', ARRAY['emotions, instincts', 'subconscious', 'empathetic, mystical', 'imaginative']);
INSERT INTO interpretation_templates (language, factor_type, factor_value_1, factor_value_2, title, content, keywords) VALUES ('vi', 'planet_in_sign', 'Moon', 'Pisces', 'Sao Moon ở Pisces', 'Với Sao Moon ở Pisces, các chủ đề về cảm xúc, bản năng và tiềm thức mang một sắc thái đồng cảm, huyền bí và giàu trí tưởng tượng. Vị trí này truyền vào bản đồ sao của bạn những đặc điểm độc đáo, kết hợp năng lượng cốt lõi của hành tinh với đặc tính và nguyên tố của cung hoàng đạo.', ARRAY['cảm xúc, bản năng', 'tiềm thức', 'đồng cảm, huyền bí', 'giàu trí tưởng tượng']);
INSERT INTO interpretation_templates (language, factor_type, factor_value_1, factor_value_2, title, content, keywords) VALUES ('en', 'planet_in_sign', 'Mercury', 'Aries', 'Mercury in Aries', 'With Mercury in Aries, the themes of communication and intellect take on a direct, pioneering, and energetic flavor. This placement infuses your chart with unique characteristics, blending the planet''s core energy with the sign''s modality and element.', ARRAY['communication and intellect', 'direct, pioneering', 'energetic']);
INSERT INTO interpretation_templates (language, factor_type, factor_value_1, factor_value_2, title, content, keywords) VALUES ('vi', 'planet_in_sign', 'Mercury', 'Aries', 'Sao Mercury ở Aries', 'Với Sao Mercury ở Aries, các chủ đề về giao tiếp và trí tuệ mang một sắc thái trực tiếp, tiên phong và tràn đầy năng lượng. Vị trí này truyền vào bản đồ sao của bạn những đặc điểm độc đáo, kết hợp năng lượng cốt lõi của hành tinh với đặc tính và nguyên tố của cung hoàng đạo.', ARRAY['giao tiếp', 'trí tuệ', 'trực tiếp, tiên phong', 'tràn đầy năng lượng']);
INSERT INTO interpretation_templates (language, factor_type, factor_value_1, factor_value_2, title, content, keywords) VALUES ('en', 'planet_in_sign', 'Mercury', 'Taurus', 'Mercury in Taurus', 'With Mercury in Taurus, the themes of communication and intellect take on a grounded, persistent, and sensual flavor. This placement infuses your chart with unique characteristics, blending the planet''s core energy with the sign''s modality and element.', ARRAY['communication and intellect', 'grounded, persistent', 'sensual']);
