INSERT INTO interpretation_templates (language, factor_type, factor_value_1, factor_value_2, title, content, keywords) VALUES ('en', 'planet_in_sign', 'Mercury', 'Gemini', 'Mercury in Gemini', 'With Mercury in Gemini, the themes of communication and intellect take on a curious, adaptable, and communicative flavor. This placement infuses your chart with unique characteristics, blending the planet''s core energy with the sign''s modality and element.', ARRAY['communication and intellect', 'curious, adaptable', 'communicative']);
INSERT INTO interpretation_templates (language, factor_type, factor_value_1, factor_value_2, title, content, keywords) VALUES ('vi', 'planet_in_sign', 'Mercury', 'Gemini', 'Sao Mercury ở Gemini', 'Với Sao Mercury ở Gemini, các chủ đề về giao tiếp và trí tuệ mang một sắc thái tò mò, dễ thích nghi và hoạt ngôn. Vị trí này truyền vào bản đồ sao của bạn những đặc điểm độc đáo, kết hợp năng lượng cốt lõi của hành tinh với đặc tính và nguyên tố của cung hoàng đạo.', ARRAY['giao tiếp', 'trí tuệ', 'tò mò, dễ thích nghi', 'hoạt ngôn']);
INSERT INTO interpretation_templates (language, factor_type, factor_value_1, factor_value_2, title, content, keywords) VALUES ('en', 'planet_in_sign', 'Mercury', 'Cancer', 'Mercury in Cancer', 'With Mercury in Cancer, the themes of communication and intellect take on a intuitive, nurturing, and emotional flavor. This placement infuses your chart with unique characteristics, blending the planet''s core energy with the sign''s modality and element.', ARRAY['communication and intellect', 'intuitive, nurturing', 'emotional']);
