INSERT INTO interpretation_templates (language, factor_type, factor_value_1, factor_value_2, title, content, keywords) VALUES ('en', 'planet_in_sign', 'Mercury', 'Leo', 'Mercury in Leo', 'With Mercury in Leo, the themes of communication and intellect take on a dramatic, expressive, and confident flavor. This placement infuses your chart with unique characteristics, blending the planet''s core energy with the sign''s modality and element.', ARRAY['communication and intellect', 'dramatic, expressive', 'confident']);
