INSERT INTO interpretation_templates (language, factor_type, factor_value_1, factor_value_2, title, content, keywords) VALUES ('en', 'planet_in_sign', 'Venus', 'Aries', 'Venus in Aries', 'With Venus in Aries, the themes of love, aesthetics, and relationships take on a direct, pioneering, and energetic flavor. This placement infuses your chart with unique characteristics, blending the planet''s core energy with the sign''s modality and element.', ARRAY['love, aesthetics', 'relationships', 'direct, pioneering', 'energetic']);
