INSERT INTO interpretation_templates (language, factor_type, factor_value_1, factor_value_2, title, content, keywords) VALUES ('en', 'planet_in_sign', 'Jupiter', 'Aries', 'Jupiter in Aries', 'With Jupiter in Aries, the themes of expansion, luck, and philosophy take on a direct, pioneering, and energetic flavor. This placement infuses your chart with unique characteristics, blending the planet''s core energy with the sign''s modality and element.', ARRAY['expansion, luck', 'philosophy', 'direct, pioneering', 'energetic']);
INSERT INTO interpretation_templates (language, factor_type, factor_value_1, factor_value_2, title, content, keywords) VALUES ('vi', 'planet_in_sign', 'Jupiter', 'Aries', 'Sao Jupiter ở Aries', 'Với Sao Jupiter ở Aries, các chủ đề về sự mở rộng, may mắn và triết lý mang một sắc thái trực tiếp, tiên phong và tràn đầy năng lượng. Vị trí này truyền vào bản đồ sao của bạn những đặc điểm độc đáo, kết hợp năng lượng cốt lõi của hành tinh với đặc tính và nguyên tố của cung hoàng đạo.', ARRAY['sự mở rộng, may mắn', 'triết lý', 'trực tiếp, tiên phong', 'tràn đầy năng lượng']);
