INSERT INTO interpretation_templates (language, factor_type, factor_value_1, factor_value_2, title, content, keywords) VALUES ('en', 'planet_in_sign', 'Jupiter', 'Pisces', 'Jupiter in Pisces', 'With Jupiter in Pisces, the themes of expansion, luck, and philosophy take on a empathetic, mystical, and imaginative flavor. This placement infuses your chart with unique characteristics, blending the planet''s core energy with the sign''s modality and element.', ARRAY['expansion, luck', 'philosophy', 'empathetic, mystical', 'imaginative']);
