INSERT INTO interpretation_templates (language, factor_type, factor_value_1, factor_value_2, title, content, keywords) VALUES ('en', 'planet_in_sign', 'Neptune', 'Sagittarius', 'Neptune in Sagittarius', 'With Neptune in Sagittarius, the themes of dreams, illusion, and spirituality take on a adventurous, philosophical, and optimistic flavor. This placement infuses your chart with unique characteristics, blending the planet''s core energy with the sign''s modality and element.', ARRAY['dreams, illusion', 'spirituality', 'adventurous, philosophical', 'optimistic']);
