INSERT INTO interpretation_templates (language, factor_type, factor_value_1, factor_value_2, title, content, keywords) VALUES ('en', 'planet_in_sign', 'Pluto', 'Aries', 'Pluto in Aries', 'With Pluto in Aries, the themes of transformation, power, and rebirth take on a direct, pioneering, and energetic flavor. This placement infuses your chart with unique characteristics, blending the planet''s core energy with the sign''s modality and element.', ARRAY['transformation, power', 'rebirth', 'direct, pioneering', 'energetic']);
