INSERT INTO interpretation_templates (language, factor_type, factor_value_1, factor_value_2, title, content, keywords) VALUES ('vi', 'planet_in_house', 'Sun', '12', 'Sao Sun ở Nhà 12', 'Sở hữu Sao Sun ở Nhà 12 hướng năng lượng của bản sắc cốt lõi, sức sống và cái tôi vào các vấn đề liên quan đến tâm linh, tiềm thức và những điều ẩn giấu. Điều này chỉ ra một lĩnh vực trọng tâm và phát triển quan trọng trong suốt cuộc đời của bạn.', ARRAY['bản sắc cốt lõi, sức sống', 'cái tôi', 'Nhà 12']);
INSERT INTO interpretation_templates (language, factor_type, factor_value_1, factor_value_2, title, content, keywords) VALUES ('en', 'planet_in_house', 'Moon', '1', 'Moon in the 1 House', 'Having Moon in the 1 House directs the energy of emotions, instincts, and subconscious towards matters of personal identity, appearance, and first impressions. This indicates a significant area of focus and development throughout your life.', ARRAY['emotions, instincts', 'subconscious', 'House 1']);
INSERT INTO interpretation_templates (language, factor_type, factor_value_1, factor_value_2, title, content, keywords) VALUES ('vi', 'planet_in_house', 'Moon', '1', 'Sao Moon ở Nhà 1', 'Sở hữu Sao Moon ở Nhà 1 hướng năng lượng của cảm xúc, bản năng và tiềm thức vào các vấn đề liên quan đến bản sắc cá nhân, ngoại hình và ấn tượng đầu tiên. Điều này chỉ ra một lĩnh vực trọng tâm và phát triển quan trọng trong suốt cuộc đời của bạn.', ARRAY['cảm xúc, bản năng', 'tiềm thức', 'Nhà 1']);
INSERT INTO interpretation_templates (language, factor_type, factor_value_1, factor_value_2, title, content, keywords) VALUES ('en', 'planet_in_house', 'Moon', '2', 'Moon in the 2 House', 'Having Moon in the 2 House directs the energy of emotions, instincts, and subconscious towards matters of material possessions, self-worth, and values. This indicates a significant area of focus and development throughout your life.', ARRAY['emotions, instincts', 'subconscious', 'House 2']);
INSERT INTO interpretation_templates (language, factor_type, factor_value_1, factor_value_2, title, content, keywords) VALUES ('vi', 'planet_in_house', 'Moon', '2', 'Sao Moon ở Nhà 2', 'Sở hữu Sao Moon ở Nhà 2 hướng năng lượng của cảm xúc, bản năng và tiềm thức vào các vấn đề liên quan đến tài sản vật chất, giá trị bản thân và giá trị cốt lõi. Điều này chỉ ra một lĩnh vực trọng tâm và phát triển quan trọng trong suốt cuộc đời của bạn.', ARRAY['cảm xúc, bản năng', 'tiềm thức', 'Nhà 2']);
