INSERT INTO interpretation_templates (language, factor_type, factor_value_1, factor_value_2, title, content, keywords) VALUES ('vi', 'planet_in_house', 'Mercury', '9', 'Sao Mercury ở Nhà 9', 'Sở hữu Sao Mercury ở Nhà 9 hướng năng lượng của giao tiếp và trí tuệ vào các vấn đề liên quan đến học thức cao, du lịch xa và niềm tin. Điều này chỉ ra một lĩnh vực trọng tâm và phát triển quan trọng trong suốt cuộc đời của bạn.', ARRAY['giao tiếp', 'trí tuệ', 'Nhà 9']);
INSERT INTO interpretation_templates (language, factor_type, factor_value_1, factor_value_2, title, content, keywords) VALUES ('en', 'planet_in_house', 'Mercury', '10', 'Mercury in the 10 House', 'Having Mercury in the 10 House directs the energy of communication and intellect towards matters of career, public standing, and long-term goals. This indicates a significant area of focus and development throughout your life.', ARRAY['communication and intellect', 'House 10']);
INSERT INTO interpretation_templates (language, factor_type, factor_value_1, factor_value_2, title, content, keywords) VALUES ('vi', 'planet_in_house', 'Mercury', '10', 'Sao Mercury ở Nhà 10', 'Sở hữu Sao Mercury ở Nhà 10 hướng năng lượng của giao tiếp và trí tuệ vào các vấn đề liên quan đến sự nghiệp, danh tiếng và mục tiêu dài hạn. Điều này chỉ ra một lĩnh vực trọng tâm và phát triển quan trọng trong suốt cuộc đời của bạn.', ARRAY['giao tiếp', 'trí tuệ', 'Nhà 10']);
INSERT INTO interpretation_templates (language, factor_type, factor_value_1, factor_value_2, title, content, keywords) VALUES ('en', 'planet_in_house', 'Mercury', '11', 'Mercury in the 11 House', 'Having Mercury in the 11 House directs the energy of communication and intellect towards matters of friendships, networks, and collective goals. This indicates a significant area of focus and development throughout your life.', ARRAY['communication and intellect', 'House 11']);
INSERT INTO interpretation_templates (language, factor_type, factor_value_1, factor_value_2, title, content, keywords) VALUES ('vi', 'planet_in_house', 'Mercury', '11', 'Sao Mercury ở Nhà 11', 'Sở hữu Sao Mercury ở Nhà 11 hướng năng lượng của giao tiếp và trí tuệ vào các vấn đề liên quan đến tình bạn, mạng lưới quan hệ và mục tiêu tập thể. Điều này chỉ ra một lĩnh vực trọng tâm và phát triển quan trọng trong suốt cuộc đời của bạn.', ARRAY['giao tiếp', 'trí tuệ', 'Nhà 11']);
INSERT INTO interpretation_templates (language, factor_type, factor_value_1, factor_value_2, title, content, keywords) VALUES ('en', 'planet_in_house', 'Mercury', '12', 'Mercury in the 12 House', 'Having Mercury in the 12 House directs the energy of communication and intellect towards matters of spirituality, subconscious, and hidden matters. This indicates a significant area of focus and development throughout your life.', ARRAY['communication and intellect', 'House 12']);
INSERT INTO interpretation_templates (language, factor_type, factor_value_1, factor_value_2, title, content, keywords) VALUES ('vi', 'planet_in_house', 'Mercury', '12', 'Sao Mercury ở Nhà 12', 'Sở hữu Sao Mercury ở Nhà 12 hướng năng lượng của giao tiếp và trí tuệ vào các vấn đề liên quan đến tâm linh, tiềm thức và những điều ẩn giấu. Điều này chỉ ra một lĩnh vực trọng tâm và phát triển quan trọng trong suốt cuộc đời của bạn.', ARRAY['giao tiếp', 'trí tuệ', 'Nhà 12']);
INSERT INTO interpretation_templates (language, factor_type, factor_value_1, factor_value_2, title, content, keywords) VALUES ('en', 'planet_in_house', 'Venus', '1', 'Venus in the 1 House', 'Having Venus in the 1 House directs the energy of love, aesthetics, and relationships towards matters of personal identity, appearance, and first impressions. This indicates a significant area of focus and development throughout your life.', ARRAY['love, aesthetics', 'relationships', 'House 1']);
INSERT INTO interpretation_templates (language, factor_type, factor_value_1, factor_value_2, title, content, keywords) VALUES ('vi', 'planet_in_house', 'Venus', '1', 'Sao Venus ở Nhà 1', 'Sở hữu Sao Venus ở Nhà 1 hướng năng lượng của tình yêu, thẩm mỹ và các mối quan hệ vào các vấn đề liên quan đến bản sắc cá nhân, ngoại hình và ấn tượng đầu tiên. Điều này chỉ ra một lĩnh vực trọng tâm và phát triển quan trọng trong suốt cuộc đời của bạn.', ARRAY['tình yêu, thẩm mỹ', 'các mối quan hệ', 'Nhà 1']);
INSERT INTO interpretation_templates (language, factor_type, factor_value_1, factor_value_2, title, content, keywords) VALUES ('en', 'planet_in_house', 'Venus', '2', 'Venus in the 2 House', 'Having Venus in the 2 House directs the energy of love, aesthetics, and relationships towards matters of material possessions, self-worth, and values. This indicates a significant area of focus and development throughout your life.', ARRAY['love, aesthetics', 'relationships', 'House 2']);
