INSERT INTO interpretation_templates (language, factor_type, factor_value_1, factor_value_2, title, content, keywords) VALUES ('en', 'planet_in_house', 'Mars', '6', 'Mars in the 6 House', 'Having Mars in the 6 House directs the energy of action, drive, and desire towards matters of daily work, routines, and physical health. This indicates a significant area of focus and development throughout your life.', ARRAY['action, drive', 'desire', 'House 6']);
