INSERT INTO interpretation_templates (language, factor_type, factor_value_1, factor_value_2, title, content, keywords) VALUES ('vi', 'planet_in_house', 'Saturn', '1', 'Sao Saturn ở Nhà 1', 'Sở hữu Sao Saturn ở Nhà 1 hướng năng lượng của hạn chế, kỷ luật và trách nhiệm vào các vấn đề liên quan đến bản sắc cá nhân, ngoại hình và ấn tượng đầu tiên. Điều này chỉ ra một lĩnh vực trọng tâm và phát triển quan trọng trong suốt cuộc đời của bạn.', ARRAY['hạn chế, kỷ luật', 'trách nhiệm', 'Nhà 1']);
