INSERT INTO interpretation_templates (language, factor_type, factor_value_1, factor_value_2, title, content, keywords) VALUES ('vi', 'planet_in_house', 'Saturn', '2', 'Sao Saturn ở Nhà 2', 'Sở hữu Sao Saturn ở Nhà 2 hướng năng lượng của hạn chế, kỷ luật và trách nhiệm vào các vấn đề liên quan đến tài sản vật chất, giá trị bản thân và giá trị cốt lõi. Điều này chỉ ra một lĩnh vực trọng tâm và phát triển quan trọng trong suốt cuộc đời của bạn.', ARRAY['hạn chế, kỷ luật', 'trách nhiệm', 'Nhà 2']);
INSERT INTO interpretation_templates (language, factor_type, factor_value_1, factor_value_2, title, content, keywords) VALUES ('en', 'planet_in_house', 'Saturn', '3', 'Saturn in the 3 House', 'Having Saturn in the 3 House directs the energy of restriction, discipline, and responsibility towards matters of communication, siblings, and local environment. This indicates a significant area of focus and development throughout your life.', ARRAY['restriction, discipline', 'responsibility', 'House 3']);
INSERT INTO interpretation_templates (language, factor_type, factor_value_1, factor_value_2, title, content, keywords) VALUES ('vi', 'planet_in_house', 'Saturn', '3', 'Sao Saturn ở Nhà 3', 'Sở hữu Sao Saturn ở Nhà 3 hướng năng lượng của hạn chế, kỷ luật và trách nhiệm vào các vấn đề liên quan đến giao tiếp, anh chị em và môi trường xung quanh. Điều này chỉ ra một lĩnh vực trọng tâm và phát triển quan trọng trong suốt cuộc đời của bạn.', ARRAY['hạn chế, kỷ luật', 'trách nhiệm', 'Nhà 3']);
INSERT INTO interpretation_templates (language, factor_type, factor_value_1, factor_value_2, title, content, keywords) VALUES ('en', 'planet_in_house', 'Saturn', '4', 'Saturn in the 4 House', 'Having Saturn in the 4 House directs the energy of restriction, discipline, and responsibility towards matters of home, family roots, and inner security. This indicates a significant area of focus and development throughout your life.', ARRAY['restriction, discipline', 'responsibility', 'House 4']);
INSERT INTO interpretation_templates (language, factor_type, factor_value_1, factor_value_2, title, content, keywords) VALUES ('vi', 'planet_in_house', 'Saturn', '4', 'Sao Saturn ở Nhà 4', 'Sở hữu Sao Saturn ở Nhà 4 hướng năng lượng của hạn chế, kỷ luật và trách nhiệm vào các vấn đề liên quan đến nhà cửa, nguồn cội gia đình và sự an toàn nội tâm. Điều này chỉ ra một lĩnh vực trọng tâm và phát triển quan trọng trong suốt cuộc đời của bạn.', ARRAY['hạn chế, kỷ luật', 'trách nhiệm', 'Nhà 4']);
