INSERT INTO interpretation_templates (language, factor_type, factor_value_1, factor_value_2, title, content, keywords) VALUES ('en', 'planet_in_house', 'Uranus', '1', 'Uranus in the 1 House', 'Having Uranus in the 1 House directs the energy of innovation, rebellion, and sudden change towards matters of personal identity, appearance, and first impressions. This indicates a significant area of focus and development throughout your life.', ARRAY['innovation, rebellion', 'sudden change', 'House 1']);
