INSERT INTO interpretation_templates (language, factor_type, factor_value_1, factor_value_2, title, content, keywords) VALUES ('en', 'planet_in_house', 'Uranus', '10', 'Uranus in the 10 House', 'Having Uranus in the 10 House directs the energy of innovation, rebellion, and sudden change towards matters of career, public standing, and long-term goals. This indicates a significant area of focus and development throughout your life.', ARRAY['innovation, rebellion', 'sudden change', 'House 10']);
INSERT INTO interpretation_templates (language, factor_type, factor_value_1, factor_value_2, title, content, keywords) VALUES ('vi', 'planet_in_house', 'Uranus', '10', 'Sao Uranus ở Nhà 10', 'Sở hữu Sao Uranus ở Nhà 10 hướng năng lượng của đổi mới, nổi loạn và thay đổi bất ngờ vào các vấn đề liên quan đến sự nghiệp, danh tiếng và mục tiêu dài hạn. Điều này chỉ ra một lĩnh vực trọng tâm và phát triển quan trọng trong suốt cuộc đời của bạn.', ARRAY['đổi mới, nổi loạn', 'thay đổi bất ngờ', 'Nhà 10']);
INSERT INTO interpretation_templates (language, factor_type, factor_value_1, factor_value_2, title, content, keywords) VALUES ('en', 'planet_in_house', 'Uranus', '11', 'Uranus in the 11 House', 'Having Uranus in the 11 House directs the energy of innovation, rebellion, and sudden change towards matters of friendships, networks, and collective goals. This indicates a significant area of focus and development throughout your life.', ARRAY['innovation, rebellion', 'sudden change', 'House 11']);
