INSERT INTO interpretation_templates (language, factor_type, factor_value_1, factor_value_2, title, content, keywords) VALUES ('en', 'planet_in_house', 'Neptune', '1', 'Neptune in the 1 House', 'Having Neptune in the 1 House directs the energy of dreams, illusion, and spirituality towards matters of personal identity, appearance, and first impressions. This indicates a significant area of focus and development throughout your life.', ARRAY['dreams, illusion', 'spirituality', 'House 1']);
INSERT INTO interpretation_templates (language, factor_type, factor_value_1, factor_value_2, title, content, keywords) VALUES ('vi', 'planet_in_house', 'Neptune', '1', 'Sao Neptune ở Nhà 1', 'Sở hữu Sao Neptune ở Nhà 1 hướng năng lượng của giấc mơ, ảo tưởng và tâm linh vào các vấn đề liên quan đến bản sắc cá nhân, ngoại hình và ấn tượng đầu tiên. Điều này chỉ ra một lĩnh vực trọng tâm và phát triển quan trọng trong suốt cuộc đời của bạn.', ARRAY['giấc mơ, ảo tưởng', 'tâm linh', 'Nhà 1']);
