INSERT INTO interpretation_templates (language, factor_type, factor_value_1, factor_value_2, title, content, keywords) VALUES ('en', 'planet_in_house', 'Pluto', '6', 'Pluto in the 6 House', 'Having Pluto in the 6 House directs the energy of transformation, power, and rebirth towards matters of daily work, routines, and physical health. This indicates a significant area of focus and development throughout your life.', ARRAY['transformation, power', 'rebirth', 'House 6']);
INSERT INTO interpretation_templates (language, factor_type, factor_value_1, factor_value_2, title, content, keywords) VALUES ('vi', 'planet_in_house', 'Pluto', '6', 'Sao Pluto ở Nhà 6', 'Sở hữu Sao Pluto ở Nhà 6 hướng năng lượng của biến đổi, quyền lực và tái sinh vào các vấn đề liên quan đến công việc hàng ngày, thói quen và sức khỏe thể chất. Điều này chỉ ra một lĩnh vực trọng tâm và phát triển quan trọng trong suốt cuộc đời của bạn.', ARRAY['biến đổi, quyền lực', 'tái sinh', 'Nhà 6']);
INSERT INTO interpretation_templates (language, factor_type, factor_value_1, factor_value_2, title, content, keywords) VALUES ('en', 'planet_in_house', 'Pluto', '7', 'Pluto in the 7 House', 'Having Pluto in the 7 House directs the energy of transformation, power, and rebirth towards matters of partnerships, marriage, and open enemies. This indicates a significant area of focus and development throughout your life.', ARRAY['transformation, power', 'rebirth', 'House 7']);
