INSERT INTO interpretation_templates (language, factor_type, factor_value_1, factor_value_2, title, content, keywords) VALUES ('en', 'planet_in_house', 'Pluto', '8', 'Pluto in the 8 House', 'Having Pluto in the 8 House directs the energy of transformation, power, and rebirth towards matters of transformation, shared resources, and intimacy. This indicates a significant area of focus and development throughout your life.', ARRAY['transformation, power', 'rebirth', 'House 8']);
