INSERT INTO interpretation_templates (language, factor_type, factor_value_1, factor_value_2, title, content, keywords) VALUES ('en', 'planet_in_house', 'North Node', '1', 'North Node in the 1 House', 'Having North Node in the 1 House directs the energy of karmic destiny and life purpose towards matters of personal identity, appearance, and first impressions. This indicates a significant area of focus and development throughout your life.', ARRAY['karmic destiny and life purpose', 'House 1']);
